{"code":"import json
import numpy as np
import pandas as pd
from scipy.optimize import minimize

with open("evaluations.json") as f:
    evals = json.load(f)

cols = ["pea protein", "fava bean protein", "coconut oil", "sunflower oil", "potato starch", "methylcellulose", "yeast extract", "onion", "white pepper"]
rows = []
for e in evals:
    if e["iteration"] in [1, 4, 5, 6, 7, 8, 9, 11, 12, 13, 14, 15]:
        d = {x["ingredient"]: x["fraction"] for x in e["recipe"]}
        rows.append([e["iteration"], e["target_dissimilarity"]] + [d.get(c, 0.0) for c in cols])

df = pd.DataFrame(rows, columns=["iter", "y"] + cols).set_index("iter")
print(df.sort_values("y").to_string())

X = df[cols].values
y = df["y"].values
v5 = df.loc[5, cols].values

# Notice that minor ingredients (methylcellulose, yeast extract, onion, white pepper) have MUCH smaller fractions than pea protein!
# So a 0.01 change in methylcellulose or onion is huge! We MUST allow different weights w_j for different ingredients (or inverse variance / inverse fraction weights)!
for mode in ["const_w", "inv_x", "inv_x2", "learned_diag"]:
    def loss(params):
        x_star = np.exp(params[:9])
        x_star = x_star / np.sum(x_star)
        scale = np.exp(params[9])
        y0 = 0.15
        if mode == "const_w":
            w = np.ones(9)
        elif mode == "inv_x":
            w = 1.0 / (v5 + 0.01)
        elif mode == "inv_x2":
            w = 1.0 / ((v5 + 0.02)**2)
        elif mode == "learned_diag":
            w = np.exp(params[10:19])
        dist = np.sqrt(np.sum(w * (X - x_star)**2, axis=1) + 1e-8)
        pred = y0 + scale * dist
        reg = 0.05 * np.sum((x_star - v5)**2)
        if mode == "learned_diag":
            reg += 0.1 * np.sum(params[10:19]**2)
        return np.sum((pred - y)**2) + reg

    best = None
    n_p = 19 if mode == "learned_diag" else 10
    for s in range(40):
        np.random.seed(s)
        p0 = np.concatenate([np.log(v5 + 1e-3) + np.random.randn(9)*0.05, [1.0]])
        if mode == "learned_diag":
            p0 = np.concatenate([p0, np.zeros(9)])
        res = minimize(loss, p0, method="BFGS")
        if best is None or res.fun < best.fun:
            best = res
    x_star = np.exp(best.x[:9])
    x_star /= np.sum(x_star)
    scale = np.exp(best.x[9])
    if mode == "const_w": w = np.ones(9)
    elif mode == "inv_x": w = 1.0 / (v5 + 0.01)
    elif mode == "inv_x2": w = 1.0 / ((v5 + 0.02)**2)
    elif mode == "learned_diag": w = np.exp(best.x[10:19])
    pred = 0.15 + scale * np.sqrt(np.sum(w * (X - x_star)**2, axis=1) + 1e-8)
    rmse = np.sqrt(np.mean((pred - y)**2))
    print(f"\nMode {mode:12s}: RMSE={rmse:.4f}")
    for c, val, v5_val, v14_val in zip(cols, x_star, v5, df.loc[14, cols].values):
        print(f"  {c:20s}: opt={val:.4f} (Iter5={v5_val:.4f}, Iter14={v14_val:.4f})")
"}

